'use strict';

import { META_STORE } from './util';

export default function (txn, doc, callback) {
  if (txn.error) {
    return callback(txn.error);
  }

  const id = doc._id;

  txn.txn.objectStore(META_STORE).delete(id).onsuccess = function () {
    txn.txn.commit();
    callback({ok: true, id: id, rev: '0-0'});
  };
}
